komponenten-inputs-forms-skala--formular.snippet:
import { Component } from '@angular/core';
import { ScaleComponent } from '@conciso/design-system-angular';

@Component({
  selector: 'app-demo',
  imports: [ScaleComponent],
  template: `
    <div style="display:flex;flex-direction:column;gap:var(--s3);max-width:28rem">
        <cds-scale
            label="Zufriedenheit"
            scaleId="form-scale"
            [labels]="labels"
            [formControl]="ctrl">
        </cds-scale>
        <p style="font:14px/1.4 system-ui,sans-serif;margin:0">
            Index:
            <strong>{{ ctrl.value }}</strong>
        </p>
    </div>`,
})
export class DemoComponent {
  labels = ['Sehr unzufrieden', 'Unzufrieden', 'Neutral', 'Zufrieden', 'Sehr zufrieden'];
}
